public class tr0 {
    static final int MOD = 998244353;
    static Scanner sc = new Scanner(System.in);
    public static void main(String[] args) {
        int n = sc.nextInt();
        long k = sc.nextLong();
        if (k >= n) {
            System.out.println(0);
            return;
        }
        long[] fact = new long[n + 1];
        fact[0] = 1;
        for (int i = 1; i <= n; i++) {
            fact[i] = (fact[i - 1] * i) % MOD;
        }
        if (k == 0) {
            System.out.println(fact[n]);
            return;
        }
        int c = (int) (n - k);
        long invFactC = modInverse(fact[c], MOD);
        long invFactNMinusC = modInverse(fact[n - c], MOD);
        long ans = fact[n] * invFactC % MOD * invFactNMinusC % MOD;
        long sum = 0;
        for (int i = 0; i <= c; i++) {
            long term;
            if (i % 2 == 0) {
                term = fact[c] * modPow(invFact(i), MOD - 2) % MOD;
                term = term * modPow(invFact(c - i), MOD - 2) % MOD;
                term = term * modPow(c - i, n) % MOD;
                sum = (sum + term) % MOD;
            } else {
                long temp = fact[c] * modPow(invFact(i), MOD - 2) % MOD;
                temp = temp * modPow(invFact(c - i), MOD - 2) % MOD;
                temp = temp * modPow(c - i, n) % MOD;
                sum = (sum - temp + MOD) % MOD;
            }
        }
        ans = ans * 2 % MOD * sum % MOD;
        System.out.println(ans);
    }

    static long modPow(long base, long exp) {
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1)
                result = (result * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return result;
    }

    static long modInverse(long a, int m) {
        return modPow(a, m - 2);
    }
}
